-- DeathSound - Shared.lua
-- Shared namespace `ns` (see TOC order): ns.L (locale), ns.SoundList, ns.ImageList
-- (both in Data\MediaLists.lua, generated by UpdateLists.bat), shared constants,
-- ns.defaults (other files add their keys when they load) and the list lookup helpers.

local _, ns = ...

ns.PREFIX          = "|cff00ccff[DeathSound]|r "
ns.DROPDOWN_WIDTH  = 160
ns.COL_WIDTH       = 350   -- left column of the tabs
ns.SoundList       = ns.SoundList or {}
ns.ImageList       = ns.ImageList or {}
ns.isDead          = false

ns.defaults = {
    enabled      = true,
    gameSoundID  = "",
    randomSound  = false,
    soundName    = "",   -- saved name of the selected sound
    useGameSound = false,
}

-- Index of the saved name in a list (fallback: 1)
function ns.ResolveIndex(list, name)
    if name and name ~= "" then
        for i, entry in ipairs(list) do
            if entry.name == name then return i end
        end
    end
    return 1
end

-- Entry for the saved name (fallback: first entry, nil for an empty list)
function ns.ResolveEntry(list, name)
    return list[ns.ResolveIndex(list, name)]
end

-- Random index 1..count, never equal to `current` (requires count > 1)
function ns.PickRandomIndex(count, current)
    local idx = math.random(1, count - 1)
    if idx >= current then idx = idx + 1 end
    return idx
end
